// Панели и дискавери: размеры и ассеты из 4057:14853, 14705, 14742, 14825.
const LUMEN_HEAD_SRC='data:image/png;base64,';
const icon=(file)=>{if(file==='4dcdf.svg'||file==='e6a43.svg')return `<span class="lumen-head"><img src="${LUMEN_HEAD_SRC}" alt="" draggable="false"></span>`;return `<img class="ui-icon" src="assets/design/${file}" alt="" draggable="false">`;};
let densityOpen=false,editing=false,dragging=false,keyboardLatin=false,keyboardShift=false,densityDirection='right';
const nativeIOS=/iPad|iPhone|iPod/.test(navigator.userAgent)||(navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1);phone.classList.toggle('native-ios',nativeIOS);
density=100;
$('#bookbar').innerHTML=`<button id="collapse" aria-label="Свернуть чтение">${icon('6d690.svg')}</button><div class="book-label"><b id="booktitle">Анна Каренина</b><span id="author">Лев Толстой</span></div><div class="header-spacer"></div><button id="settings" aria-label="Настройки чтения">${icon('b584a.svg')}</button><button id="more" aria-label="Меню книги">${icon('85b76.svg')}</button>`;
$('#footer').innerHTML=`<button id="mini" hidden aria-label="Вернуться к чтению"><img id="miniCover" src="assets/design/666ab.png" alt=""><span class="mini-title"><b></b><small></small></span><span class="mini-spacer"></span><span class="mini-cta">К чтению</span></button><div id="progress" hidden><input id="seek" type="range" aria-label="Позиция в ленте" min="0" max="10000" step="1" value="0"></div><div class="controlrow"><button id="spark" class="round glass" aria-label="Настроить количество ИИ-вставок">${icon('4dcdf.svg')}</button><form id="queryForm" class="glass"><span id="discoverySpark">${icon('e6a43.svg')}</span><input id="ask" type="text" inputmode="text" enterkeyhint="send" autocomplete="off" spellcheck="false" aria-label="Запрос" placeholder="Что будем читать?"><button id="sendInline" type="submit" hidden aria-label="Отправить запрос">↑</button></form><div id="densityInline" class="glass" hidden><div class="density-track"><div id="densityFill"></div><div class="density-ticks"></div><div class="density-ticks filled-ticks"></div></div><input aria-label="Степень ИИ" type="range" min="0" max="100" step="1" value="100"></div><button id="startAudio" class="round glass" aria-label="Включить плеер">${icon('c257f.svg')}</button><div id="audio" hidden><button id="rewind" class="glass" aria-label="Назад 15 секунд">${icon('aa08f.svg')}<small>15</small></button><button id="play" class="glass" aria-label="Пауза">${icon('ce6bc.svg')}</button><button id="forward" class="glass" aria-label="Вперёд 30 секунд">${icon('76457.svg')}<small>30</small></button></div></div><div id="context"></div>`;
$('#floating').innerHTML=icon('4dcdf.svg');$('#floating').classList.add('glass');
const discovery=document.createElement('div');discovery.id='discovery';discovery.hidden=true;
discovery.innerHTML=`<img class="discovery-avatar" src="assets/design/b686d.png" alt="Полина"><h2>Доброе утро, Полина!<br>найдем что-то новое?</h2><div class="discovery-recs"><div class="discovery-columns"></div></div><h3>Хотели прочитать</h3><div class="discovery-saved"><div class="discovery-columns"></div></div>`;
phone.insertBefore(discovery,$('#status'));
const keyboard=document.createElement('section');keyboard.id='iosKeyboard';keyboard.hidden=true;keyboard.setAttribute('aria-label','Клавиатура iOS');phone.append(keyboard);
function drawKeyboard(){
 const rows=keyboardLatin?['qwertyuiop','asdfghjkl','zxcvbnm']:['йцукенгшщзх','фывапролджэ','ячсмитьбю'];
 keyboard.innerHTML=rows.map((r,i)=>'<div class="key-row row-'+i+'">'+(i===2?'<button class="modifier icon-key" data-key="shift" aria-label="Заглавные буквы">'+icon('57d91.svg')+'</button>':'')+[...r].map(k=>'<button data-key="'+k+'">'+(keyboardShift?k.toUpperCase():k)+'</button>').join('')+(i===2?'<button class="modifier icon-key" data-key="backspace" aria-label="Удалить символ">'+icon('f0d9e.svg')+'</button>':'')+'</div>').join('')+'<div class="key-row bottom-row"><button class="modifier" data-key="numbers">123</button><button class="space" data-key="space">пробел</button><button class="return" data-key="send">ввод</button></div><div class="keyboard-tools"><button data-key="lang" aria-label="Сменить язык">'+icon('ed507.svg')+'</button><span>'+icon('2349e.svg')+'</span></div><div class="keyboard-indicator"></div>';
 keyboard.querySelectorAll('button').forEach(b=>{b.onpointerdown=e=>e.preventDefault();b.onclick=()=>keyPress(b.dataset.key);});
}
function keyPress(key){const input=$('#ask');if(key==='close'){endEditing();return}if(key==='send'){sendQuery();return}if(key==='lang'){keyboardLatin=!keyboardLatin;drawKeyboard();return}if(key==='shift'){keyboardShift=!keyboardShift;drawKeyboard();return}if(key==='numbers'){keyboardLatin=true;keyboard.innerHTML=['1234567890','-/:;()₽&@"','.,?!\''].map(r=>'<div class="key-row">'+[...r].map(k=>'<button>'+k+'</button>').join('')+'</div>').join('')+'<div class="key-row"><button data-key="lang">АБВ</button><button data-key="space">пробел</button><button data-key="send">отправить</button></div>';keyboard.querySelectorAll('button').forEach(b=>{b.onpointerdown=e=>e.preventDefault();b.onclick=()=>b.dataset.key?keyPress(b.dataset.key):insertText(b.textContent)});return}if(key==='backspace'){const start=input.selectionStart??input.value.length,end=input.selectionEnd??start;input.setRangeText('',start===end?Math.max(0,start-1):start,end,'end');input.dispatchEvent(new Event('input'));return}insertText(key==='space'?' ':keyboardShift?key.toUpperCase():key);if(keyboardShift){keyboardShift=false;drawKeyboard()}}
function insertText(text){const input=$('#ask');input.setRangeText(text,input.selectionStart??input.value.length,input.selectionEnd??input.value.length,'end');input.dispatchEvent(new Event('input'));}
function beginEditing(){if(editing)return;editing=true;densityOpen=false;showControls(true);phone.classList.add('editing');keyboard.hidden=nativeIOS;if(!nativeIOS)drawKeyboard();const input=$('#ask');input.focus({preventScroll:true});input.setSelectionRange(input.value.length,input.value.length);update();}
let keyboardDismissTimer;function endEditing(){if(!editing)return;editing=false;keyboard.hidden=true;phone.classList.remove('editing');$('#ask').blur();showControls(true);scrollLock=true;clearTimeout(keyboardDismissTimer);keyboardDismissTimer=setTimeout(()=>{scrollLock=false;},340);update();}
composer=(prefill='')=>{close();if(prefill)$('#ask').value=prefill;beginEditing();$('#ask').focus();};
function sendQuery(){const q=$('#ask').value.trim();if(!q){endEditing();return;}$('#ask').value='';endEditing();if(collapsed){collapsed=false;discovery.hidden=true;sc.style.visibility='visible';sc.scrollTop=saved;}submit(q);update();}
$('#queryForm').onsubmit=e=>{e.preventDefault();sendQuery()};$('#ask').onfocus=beginEditing;$('#ask').onpointerdown=e=>{if(editing){e.preventDefault();e.stopPropagation();endEditing();}};$('#ask').oninput=()=>{$('#sendInline').hidden=!$('#ask').value.trim();};
phone.addEventListener('pointerdown',e=>{if(editing&&!e.target.closest('#footer,#iosKeyboard'))endEditing();});
document.addEventListener('keydown',e=>{if(e.key==='Escape')endEditing()});for(const surface of [sc,discovery]){surface.addEventListener('wheel',()=>{if(editing)endEditing();},{capture:true,passive:true});surface.addEventListener('touchmove',()=>{if(editing)endEditing();},{capture:true,passive:true});surface.addEventListener('scroll',()=>{if(editing)endEditing();},{passive:true});}
